{
 "summary": "The Lean theorem states the following. Let M be a smooth, compact, connected, boundaryless Riemannian manifold of dimension n ≥ 2 whose metric distance is the Riemannian distance. If the cost c = d²/2 satisfies weak MTW, meaning −(3/2)∂²_s∂²_t c(exp_x(tξ), exp_x(v+sη))|₀ ≥ 0 for all v ∈ I(x) and all ξ ⊥ η, then every tangent injectivity domain I(x) = {v : ∃a>1, d(x, exp_x(av)) = a|v|} is convex. This matches Theorem 1.1. The main caveat is that exp is built by hand from a locally-distance-realizing characterization of geodesics, and the norm/inner product on TangentSpace are assumed to resolve to the Riemannian ones. Both points are plausible but worth a quick probe. Theorem 1.2 is not formalized.",
 "glossary": [
  {"decl": "WeakMTW.CompleteGeodesicWithInitialData", "line": 24, "plain": "γ: ℝ→M is smooth, γ(0)=x, γ'(0)=v, and γ is locally an isometric embedding at speed |v| (d(γ s, γ r) = |v||s−r| for s, r near any t).", "standard_concept": "complete geodesic with initial data (x,v)", "matches_standard": "yes", "note": "A smooth, constant-speed, locally minimizing curve is a geodesic. This relies on ‖v‖ being the Riemannian norm and on IsRiemannianManifold, which identifies dist with the Riemannian distance."},
  {"decl": "WeakMTW.exp", "line": 36, "plain": "exp_x(v) = γ(1) for a chosen such geodesic; defaults to x if none exists.", "standard_concept": "Riemannian exponential map", "matches_standard": "yes", "note": "On a compact manifold, geodesics exist (Hopf–Rinow) and are unique, so the default branch never fires and the choice is canonical."},
  {"decl": "WeakMTW.injectivityDomain", "line": 41, "plain": "I(x) = {v ∈ T_xM : ∃ a>1, d(x, exp_x(a v)) = a|v|}", "standard_concept": "open tangent injectivity domain I(x)", "matches_standard": "yes", "note": "Equivalent to the geodesic t ↦ exp_x(tv) being minimizing slightly beyond t=1, i.e. the standard interior of the minimizing domain. The paper's exact definition is not in the excerpt."},
  {"decl": "WeakMTW.cost", "line": 44, "plain": "c(x,y) = d(x,y)²/2", "standard_concept": "quadratic Riemannian cost", "matches_standard": "yes", "note": ""},
  {"decl": "WeakMTW.mtw", "line": 46, "plain": "S_(x,v)(ξ,η) = −(3/2) ∂²_s ∂²_t c(exp_x(tξ), exp_x(v+sη)) at s=t=0, using nested one-variable derivatives.", "standard_concept": "Ma–Trudinger–Wang tensor (Villani's formula)", "matches_standard": "yes", "note": "For v ∈ I(x), the cost is smooth near the relevant points, so the deriv junk values do not arise."},
  {"decl": "WeakMTW.HasWeakMTW", "line": 51, "plain": "For all x, all v ∈ I(x), and all ξ, η with ⟨ξ,η⟩=0: S_(x,v)(ξ,η) ≥ 0.", "standard_concept": "weak MTW condition (1.3)", "matches_standard": "yes", "note": "Orthogonality must use the Riemannian inner product (instance resolution)."},
  {"decl": "WeakMTW.MainConvexity", "line": 55, "plain": "For every x ∈ M, I(x) is a convex subset of T_xM.", "standard_concept": "convexity of injectivity domains", "matches_standard": "yes", "note": ""}
 ],
 "lean_claims": [
  {"theorem": "current_main_convexity", "line": 63, "plain": "Assume n ≥ 2 and M is a smooth (C^∞) manifold modeled on ℝⁿ without boundary, compact and connected. Assume it carries a smooth Riemannian metric whose induced distance is the metric of M. If the weak MTW condition holds, then I(x) is convex for every x ∈ M."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "On a smooth, connected, compact Riemannian manifold without boundary, of dimension ≥ 2, the weak MTW condition (1.3) implies that I(x) is convex for every x."},
  {"ref": "Theorem 1.2", "plain": "Under (1.3), potentials enjoy global support, intermediate-time homeomorphism, convex lifted sections and C^{1,1} intermediate regularity."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.1", "lean_theorem": "current_main_convexity", "relation": "equivalent", "why": "Same hypotheses (compact, connected, boundaryless, smooth, n≥2, weak MTW) and same conclusion (linear convexity of I(x))."},
  {"paper_ref": "Theorem 1.2", "lean_theorem": null, "relation": "not_formalized", "why": "Only the convexity corollary is stated."},
  {"paper_ref": "Theorem 4.9 (convexity of G_x)", "lean_theorem": null, "relation": "not_formalized", "why": "Only I(x) convexity is stated."}
 ],
 "flags": [
  {"id": "F1", "category": "definition-mismatch", "severity": "low", "decl": "WeakMTW.HasWeakMTW", "line": 53, "paper_ref": "(1.3)", "explanation": "TangentSpace (model n) x is definitionally EuclideanSpace ℝ (Fin n). If `inner ℝ ξ η` or `‖v‖` (line 31) resolved to the chart Euclidean structure instead of the RiemannianBundle structure, then orthogonality and speed would be wrong. The resulting definitions would differ from the paper's. Most likely the bundle instance is used, since TangentSpace is not reducible.", "polarity": "unclear", "probe_idea": "example (x : M) (v w : TangentSpace (model n) x) : inner ℝ v w = (RiemannianBundle.g.inner x) v w := rfl"},
  {"id": "F2", "category": "definition-mismatch", "severity": "low", "decl": "WeakMTW.exp", "line": 36, "paper_ref": null, "explanation": "exp is defined via choice over curves that are smooth, have velocity v at 0, and are locally distance-realizing at speed |v|. This agrees with the Riemannian exponential map only if such curves exist and are unique. That holds on compact Riemannian manifolds, but it is not checked definitionally.", "polarity": "unclear", "probe_idea": "Prove ∀ x v, ∃! y, ExpEndpoint x v y under the theorem's hypotheses."},
  {"id": "F3", "category": "coverage", "severity": "low", "decl": "current_main_convexity", "line": 63, "paper_ref": "Theorem 1.2", "explanation": "The global support and intermediate geometry results are not formalized.", "polarity": "n/a", "probe_idea": null}
 ],
 "lint_verdicts": [
  {"line": 31, "rule": "nat-sub", "verdict": "harmless", "why": "s − r is real subtraction, not ℕ."},
  {"line": 39, "rule": "classical-choose", "verdict": "harmless", "why": "On a compact manifold the geodesic endpoint exists and is unique, so the choice is canonical and the default never fires."},
  {"line": 44, "rule": "junk-div", "verdict": "harmless", "why": "Division by the literal 2 in ℝ."},
  {"line": 47, "rule": "junk-div", "verdict": "harmless", "why": "Constant 3/2 in ℝ."},
  {"line": 47, "rule": "junk-deriv", "verdict": "harmless", "why": "For v ∈ I(x) (an open set avoiding cut points), the composite is smooth near s=t=0, so deriv is the true derivative. In any case the derivative appears only inside a hypothesis."},
  {"line": 48, "rule": "junk-deriv", "verdict": "harmless", "why": "Same smoothness argument; outer derivatives at 0 depend only on nearby values, where the inner function is genuinely differentiable."},
  {"line": 49, "rule": "junk-deriv", "verdict": "harmless", "why": "c(exp_x(tξ), exp_x(v+sη)) is smooth for small s, t when exp_x v is not a cut point of x."}
 ]
}
